for name,(x,y,w,h,pts) in frames.items():
    scale=4;mask=Image.new('L',(w*scale,h*scale),0); d=ImageDraw.Draw(mask); d.polygon([(px*scale,py*scale) for px,py in pts],fill=255)
    mask=mask.resize((w,h),Image.Resampling.LANCZOS)
    crop=sheet.crop((x,y,x+w,y+h)); crop.putalpha(mask)
    pix=crop.load()
    for yy in range(h):
        for xx in range(w):
            r,g,b,a=pix[xx,yy]
            if not a: continue
            lum=.2126*r+.7152*g+.0722*b
            if lum<15: a=0
            elif lum<26: a=int(a*(lum-15)/11)
            pix[xx,yy]=(r,g,b,a)
    crop=crop.crop(mask.getbbox())
    crop.save(assets/'ships'/f'SpaceInvaders-sprite-{name}.png',optimize=True)
print('saved transparent sprite cutouts from the approved roster art')
